const t=(key)=>dict[state.locale]?.[key]??key;
const el=(id)=>document.getElementById(id);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(c)=>new Intl.NumberFormat(state.locale==='ru'?'ru-RU':'en-US',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format((c||0)/100);
const showDate=(v)=>v?new Date(v).toLocaleDateString(state.locale==='ru'?'ru-RU':'en-GB'):'—';
const status=(v)=>`<span class="status ${esc(v)}">${esc(v||'—')}</span>`;
const navItems=[['overview','home'],['quotes','quotes'],['projects','projects'],['billing','billing'],['referrals','referrals'],['support','support'],['team','team'],['admin','admin']];
const nav=(section,icon,cls='')=>`<button type="button" class="nav-link ${state.section===section?'active':''} ${cls}" data-section="${section}">${ic(icon)}<span>${t(section==='overview'?'home':section)}</span></button>`;
function toast(message,error=false){document.querySelector('.toast')?.remove();const x=document.createElement('div');x.className=`toast ${error?'error':''}`;x.textContent=message;document.body.append(x);setTimeout(()=>x.remove(),4400)}
async function api(path,opts={}){
 const headers={'accept':'application/json'};
 if(opts.body!==undefined)headers['content-type']='application/json';
 if(state.me?.csrf&&opts.method&&opts.method!=='GET')headers['x-csrf-token']=state.me.csrf;
 const response=await fetch('/api'+path,{credentials:'same-origin',...opts,headers:{...headers,...(opts.headers||{})},body:opts.body===undefined?undefined:JSON.stringify(opts.body)});
 let data;try{data=await response.json()}catch{throw new Error('Unexpected server response')}
 if(!response.ok||!data.ok)throw new Error(data.error||'Request failed');return data;
}
async function loadMe(){const x=await api('/me');state.me=x;state.locale=x.user?.locale||state.locale;state.orgId=state.orgId&&x.organizations.find(y=>y.id===state.orgId)?state.orgId:x.organizations?.[0]?.id||null;}
async function loadSection(){if(!state.me?.authenticated)return;
 const org=encodeURIComponent(state.orgId||'');
 try{
  if(['overview','quotes','projects'].includes(state.section))state.cache.quotes=(await api(`/quotes?orgId=${org}`)).quotes;
  if(['overview','billing'].includes(state.section))state.cache.invoices=(await api(`/invoices?orgId=${org}`)).invoices;
  if(state.section==='projects'){const [a,b]=await Promise.all([api(`/projects?orgId=${org}`),api(`/projects/metrics?orgId=${org}`)]);state.cache.projects=a.projects;state.cache.projectMetrics=b.metrics;}
  if(state.section==='billing')state.cache.subscription=(await api(`/subscriptions?orgId=${org}`)).subscription;
  if(['overview','referrals'].includes(state.section))state.cache.referrals=await api('/referrals/me');
  if(state.section==='support')state.cache.disputes=(await api(`/disputes?orgId=${org}`)).disputes;
  if(state.section==='admin'&&state.me.user?.is_admin){state.cache.admin=await api('/admin');state.cache.settlementReports=(await api('/admin/settlements')).reports;}
 }catch(err){toast(err.message,true)}
}
function shell(content){
 const user=state.me.user,orgs=state.me.organizations;
 return `<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-logo">P</div><div><div class="brand-copy">OSMANX <span>PROOF</span></div><div class="brand-sub">WORK OPERATING SYSTEM</div></div></div><div class="section-label">${t('workspace')}</div><nav class="nav-list">${navItems.slice(0,5).map(x=>nav(...x)).join('')}</nav><div class="section-label">${t('management')}</div><nav class="nav-list">${nav('support','support')}${nav('team','team')}${user.is_admin?nav('admin','admin'):''}</nav><div class="sidebar-bottom"><button class="btn ghost small" data-action="locale">${state.locale==='ru'?'ENGLISH':'РУССКИЙ'}</button><div class="mini-profile"><strong>${esc(user.display_name)}</strong><small>${esc(user.email)}</small></div><button class="text-button" data-action="logout">${ic('logout')} ${t('logout')}</button></div></aside><main class="main"><header class="topbar"><div class="crumb">OSMANX / ${t(state.section==='overview'?'home':state.section)}</div><div class="top-actions"><select id="orgSelect" class="select" aria-label="${t('chooseOrg')}" style="max-width:200px;padding:8px;font-size:11px">${orgs.map(o=>`<option value="${esc(o.id)}" ${o.id===state.orgId?'selected':''}>${esc(o.name)}</option>`).join('')}</select><div class="pill ${state.me.isDemo?'':'gray'}">${state.me.isDemo?t('demo'):t('real')}</div><div class="user-avatar">${esc(user.display_name?.slice(0,1)?.toUpperCase()||'U')}</div></div></header>${state.me.isDemo&&['billing'].includes(state.section)?`<div style="padding-top:22px"><div class="info-bar"><strong>SANDBOX</strong><span>${t('sandboxBanner')}</span></div></div>`:''}<div class="page">${content}</div></main><nav class="mobile-nav">${navItems.slice(0,5).map(([s,i])=>`<button class="mobile-item ${state.section===s?'active':''}" data-section="${s}">${ic(i)}<span>${t(s==='overview'?'home':s)}</span></button>`).join('')}<button class="mobile-item" data-section="team">${ic('team')}<span>${t('team')}</span></button></nav></div>`;
}
function pageTitle(title,desc,action=''){return `<header class="page-title"><div><div class="overline">OSMANX PROOF / R5</div><h1>${title}</h1><p>${desc}</p></div>${action}</header>`}
function empty(title,desc,action=''){return `<div class="empty"><strong>${title}</strong><p>${desc}</p>${action}</div>`}
function overview(){const quotes=state.cache.quotes||[],invoices=state.cache.invoices||[],r=state.cache.referrals||{},plan=state.me.organizations.find(o=>o.id===state.orgId)||{};
 const stats=[[t('quotesTotal'),quotes.length,'Всего создано'],[t('paidInvoices'),invoices.filter(x=>['paid','part_refunded'].includes(x.status)).length,'Только подтверждённые'],[t('earned'),fmt(r.totalCents||0),'Не гарантированный доход'],[t('plan'),plan.plan==='pro'?t('pro'):t('free'),plan.active_until?showDate(plan.active_until):t('trial')]];
 return `<div class="hero"><div class="hero-content"><div class="overline">${t('welcomeSmall')}</div><h1>${t('welcome')}</h1><p>${t('heroText')}</p><button class="btn primary" data-action="newquote">${ic('plus')}${t('createQuote')}</button></div><div class="hero-mark">P</div></div><div class="stats-grid">${stats.map(x=>`<div class="stat-card"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-foot">${state.locale==='ru'?x[2]:''}</div></div>`).join('')}</div><div class="layout-two"><section class="panel"><div class="panel-head"><h2>${t('recent')}</h2><button class="text-button" data-section="quotes">${t('viewAll')} →</button></div>${quotes.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('quoteTitle')}</th><th>${t('status')}</th><th>${t('date')}</th></tr></thead><tbody>${quotes.slice(0,5).map(q=>`<tr><td><button class="text-button" data-action="viewquote" data-id="${q.id}"><strong>${esc(q.title)}</strong></button></td><td>${status(q.status)}</td><td>${showDate(q.updated_at)}</td></tr>`).join('')}</tbody></table></div>`:empty(t('noQuotes'),t('noQuotesDesc'),`<button class="btn small ghost" data-action="newquote">${t('newQuote')}</button>`)}</section><section class="panel"><div class="panel-head"><h2>${t('onboarding')}</h2><span class="tag-label">01 — 03</span></div><div class="steps">${[1,2,3].map(i=>`<div class="step"><div class="step-n">0${i}</div><div><strong>${t('step'+i)}</strong><p>${t('step'+i+'d')}</p></div></div>`).join('')}</div></section></div>`;
}
function lineEditor(item={},idx=0){return `<div class="line-grid" data-line><div class="field"><label>${t('description')}</label><input class="input" name="desc" maxlength="180" value="${esc(item.description||'')}" placeholder="${state.locale==='ru'?'Например, сайт-визитка':'e.g. Landing page'}" required></div><div class="field"><label>${t('quantity')}</label><input class="input" name="qty" type="number" min="1" max="10000" step="1" value="${item.qty||1}" required></div><div class="field"><label>${t('priceUnit')}</label><input class="input" name="price" type="number" min="0" step="0.01" value="${item.unitPriceCents!==undefined?(item.unitPriceCents/100).toFixed(2):'0.00'}" required></div><div class="field"><label>${t('costUnit')}</label><input class="input" name="cost" type="number" min="0" step="0.01" value="${item.unitCostCents!==undefined?(item.unitCostCents/100).toFixed(2):'0.00'}" required></div><button type="button" data-action="remove-line" class="remove" aria-label="Remove line">×</button></div>`}
function quoteForm(){const q=state.editingQuote||{};
 return `<section class="panel" style="margin-bottom:20px"><div class="panel-head"><h2>${q.id?t('editQuote'):t('newQuote')}</h2><button class="btn ghost small" data-action="cancelquote">${t('cancel')}</button></div><form class="form" id="quoteForm"><div class="form-row"><div class="field"><label>${t('quoteTitle')}</label><input class="input" name="title" minlength="2" maxlength="140" value="${esc(q.title||'')}" placeholder="${state.locale==='ru'?'Разработка сайта':'Website design'}" required></div><div class="field"><label>${t('client')}</label><input class="input" name="clientName" maxlength="140" value="${esc(q.clientName||'')}" placeholder="ACME"></div></div><div class="field"><label>${t('clientEmail')}</label><input class="input" type="email" name="clientEmail" maxlength="254" value="${esc(q.clientEmail||'')}"></div><div class="split-header"><strong class="section-small">${t('lines')}</strong><button type="button" class="btn small ghost" data-action="add-line">${ic('plus')}${t('addLine')}</button></div><div id="quoteLines">${(q.items?.length?q.items:[{}]).map((item,i)=>lineEditor(item,i)).join('')}</div><div class="form-row"><div class="field"><label>${t('discount')}</label><input class="input" name="discount" type="number" step="0.01" min="0" value="${((q.discountCents||0)/100).toFixed(2)}"></div><div class="field"><label>${t('tax')}</label><input class="input" name="tax" type="number" step="0.01" min="0" max="100" value="${((q.taxBps||0)/100).toFixed(2)}"></div></div><div class="detail-grid"><div class="mini-kpi"><span>${t('subtotal')}</span><strong id="prevSubtotal">—</strong></div><div class="mini-kpi"><span>${t('margin')}</span><strong id="prevMargin">—</strong></div><div class="mini-kpi"><span>${t('total')}</span><strong id="prevTotal">—</strong></div></div><div class="form-actions"><button class="btn primary" type="submit">${t('saveQuote')}${ic('arrow')}</button><span class="note">${state.locale==='ru'?'Финальные значения рассчитывает сервер':'Final values are calculated server-side'}</span></div></form></section>`;
}
function quotes(){const items=state.cache.quotes||[];return `${pageTitle(t('titleQuotes'),t('descQuotes'),`<button class="btn primary" data-action="newquote">${ic('plus')}${t('newQuote')}</button>`)}${state.editingQuote!==null?quoteForm():''}<section class="panel">${items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('quoteTitle')}</th><th>${t('client')}</th><th>${t('status')}</th><th>${t('date')}</th><th>${t('actions')}</th></tr></thead><tbody>${items.map(q=>`<tr><td><strong>${esc(q.title)}</strong></td><td>${esc(q.client_name||'—')}</td><td>${status(q.status)}</td><td>${showDate(q.updated_at)}</td><td><button class="btn small ghost" data-action="viewquote" data-id="${q.id}">${t('open')}</button></td></tr>`).join('')}</tbody></table></div>`:empty(t('noQuotes'),t('noQuotesDesc'),`<button class="btn primary" data-action="newquote">${t('newQuote')}</button>`)}</section>`}
function quoteDetail(q){return `<section class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h2>${esc(q.title)}</h2><p class="note">${esc(q.clientName||'—')} · ${showDate(q.createdAt)}</p></div>${status(q.status)}</div><div class="table-wrap"><table class="table"><thead><tr><th>${t('description')}</th><th>${t('quantity')}</th><th>${t('priceUnit')}</th><th>${t('total')}</th></tr></thead><tbody>${q.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.qty}</td><td>${fmt(i.unitPriceCents)}</td><td>${fmt(i.qty*i.unitPriceCents)}</td></tr>`).join('')}</tbody></table></div><div class="detail-grid" style="margin:20px 0"><div class="mini-kpi"><span>${t('subtotal')}</span><strong>${fmt(q.math.subtotalCents)}</strong></div><div class="mini-kpi"><span>${t('margin')}</span><strong>${q.math.estimatedMarginPercent}%</strong></div><div class="mini-kpi"><span>${t('total')}</span><strong>${fmt(q.math.totalCents)}</strong></div></div><div class="form-actions"><button class="btn ghost small" data-action="editquote" data-id="${q.id}">${t('editQuote')}</button><button class="btn ghost small" data-action="printquote" data-id="${q.id}">${t('print')}</button><button class="btn ghost small" data-action="sharequote" data-id="${q.id}">${t('share')}</button>${q.status==='draft'?`<button class="btn ghost small" data-action="statusquote" data-id="${q.id}" data-status="sent">${t('markSent')}</button>`:''}${q.status==='sent'?`<button class="btn ghost small" data-action="statusquote" data-id="${q.id}" data-status="accepted">${state.locale==='ru'?'Принято вручную (не клиентом)':'Internal acceptance only'}</button>`:''}<button class="btn small" data-action="closequote">${t('cancel')}</button></div><p class="note">${state.locale==='ru'?'Версия предложения: ':'Proposal revision: '}${q.revision}. ${state.locale==='ru'?'Принятие по ссылке подтверждает действие обладателя ссылки, но не удостоверяет личность или юридическую подпись.':'Token approval records a response but does not verify legal identity or signature.'}</p>${(q.responses||[]).map(r=>`<div class="callout" style="margin-top:10px"><strong>${esc(r.decision==='accepted'?(state.locale==='ru'?'Принято клиентом':'Client accepted'):(state.locale==='ru'?'Запрошены изменения':'Changes requested'))} · v${r.revision}</strong><p>${esc(r.responderName)} · ${showDate(r.createdAt)}</p>${r.message?`<p>${esc(r.message)}</p>`:''}</div>`).join('')}<p class="note">${state.locale==='ru'?'Расчёт прибыли приблизительный; налоги бизнеса и прочие затраты учитывайте отдельно.':'Estimated profit excludes business overhead and applicable taxes.'}</p></section>`}
function billing(){const org=state.me.organizations.find(x=>x.id===state.orgId),inv=state.cache.invoices||[],pref=state.cache.subscription||{},stopped=pref.renewalState==='stopped',active=org?.plan==='pro'&&org.active_until&&new Date(org.active_until)>new Date();
 return `${pageTitle(t('subscription'),t('billingDesc'))}<div class="layout-two"><section class="plan-card"><div class="overline">THE PRODUCT, NOT THE PROMISE</div><h2>OSMANX PROOF · PRO</h2><div class="price">${fmt(state.me.proPriceCents)} <small>/ ${t('firstMonth')}</small></div><p class="note">${active?t('activePro')+' '+showDate(org.active_until):t('trial')}</p><div class="bullets">${t('proFeatures').map(x=>`<div>${esc(x)}</div>`).join('')}</div><button class="btn primary" data-action="invoice" ${stopped?'disabled':''}>${t('checkout')}</button><div class="callout" style="margin-top:14px"><strong>${state.locale==='ru'?'Управление подпиской':'Subscription control'}</strong><p>${state.locale==='ru'?'Автоматических списаний нет. Продление производится только при отдельной оплате.':'No automatic payments. Each renewal requires separate authorization.'}</p><p class="note">${stopped?(state.locale==='ru'?'Остановлено создание новых счетов. Оплаченный период сохраняется.':'New invoices are disabled; paid access remains until expiry.'):(state.locale==='ru'?'Новые счета можно создавать вручную.':'New invoices may be created manually.')}</p>${org?.role==='owner'?`<button class="btn small ghost" data-action="subscription" data-change="${stopped?'resume':'cancel'}">${stopped?(state.locale==='ru'?'Возобновить ручное продление':'Resume manual renewals'):(state.locale==='ru'?'Остановить новые счета':'Stop new invoices')}</button>`:''}</div><p class="note warning">${state.me.paymentMode==='sandbox'?t('sandboxBanner'):(state.locale==='ru'?'Платёжный шлюз пока не подключён.':'Payment provider is not yet connected.')}</p></section><section class="panel"><div class="panel-head"><h2>${t('invoiceList')}</h2></div>${inv.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('invoice')}</th><th>${t('amount')}</th><th>${t('status')}</th></tr></thead><tbody>${inv.map(i=>`<tr><td><strong>${i.id.slice(0,8)}</strong><p class="hint">${showDate(i.created_at)}</p></td><td>${fmt(i.total_cents)}${i.discount_cents?`<p class="hint">−${fmt(i.discount_cents)}</p>`:''}</td><td>${status(i.status)}${i.status==='issued'&&state.me.paymentMode==='sandbox'?`<div style="margin-top:9px"><button class="btn small primary" data-action="sandboxpay" data-id="${i.id}">${t('simulate')}</button></div>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty(t('noInvoices'),state.locale==='ru'?'Первый счёт появится после выбора тарифа.':'Choose a plan to create your first invoice.')}</section></div>`}
function referrals(){const r=state.cache.referrals||{};
 return `${pageTitle(t('refTitle'),t('refDesc'))}<div class="layout-two"><section class="panel"><div class="overline">01 / ${t('refCode')}</div><div class="ref-code" style="margin:18px 0">${esc(r.code||'—')}</div><div class="field"><label>${t('refLink')}</label><input class="input" value="${esc(r.referralUrl||'')}" id="refLink" readonly></div><div class="form-actions"><button class="btn primary" data-action="copyref">${ic('copy')}${t('copy')}</button></div><div class="detail-grid" style="margin-top:24px"><div class="mini-kpi"><span>${t('earned')}</span><strong>${fmt(r.totalCents)}</strong></div><div class="mini-kpi"><span>${t('refPending')}</span><strong>${fmt(r.pendingCents)}</strong></div><div class="mini-kpi"><span>${t('refPayable')}</span><strong>${fmt(r.availableCents)}</strong></div></div><div class="callout" style="margin-top:20px"><strong>${t('requestPayout')}</strong><p>${t('payoutWarn')}</p><form id="payoutForm" class="form"><div class="field"><label>${t('amount')} (₽; min 100)</label><input type="number" class="input" name="amount" step="0.01" min="100" max="${(r.availableCents||0)/100}" required></div><button class="btn small ghost" ${(r.availableCents||0)<10000?'disabled':''}>${t('requestPayout')}</button></form></div></section><section class="panel"><h2>${t('refRules')}</h2><div class="steps" style="margin-top:23px">${[1,2,3,4].map(i=>`<div class="step"><div class="step-n">0${i}</div><div><p>${t('refRule'+i)}</p></div></div>`).join('')}</div></section></div><section class="panel" style="margin-top:18px"><h2>${t('refHistory')}</h2>${(r.rows||[]).length?`<div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>${t('amount')}</th><th>${t('status')}</th><th>${t('date')}</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${x.id.slice(0,8)}</td><td>${fmt(x.amount_cents)}</td><td>${status(x.status)}</td><td>${showDate(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty(t('refNo'),'')}</section>`}
function support(){const ds=state.cache.disputes||[];return `${pageTitle(t('supportTitle'),t('supportDesc'))}<div class="layout-two"><section class="panel"><h2>${t('newDispute')}</h2><form id="disputeForm" class="form" style="margin-top:20px"><div class="field"><label>${t('subject')}</label><input name="subject" class="input" minlength="4" maxlength="140" required></div><div class="field"><label>${t('details')}</label><textarea name="detail" class="textarea" minlength="10" maxlength="3000" required></textarea></div><div><button class="btn primary">${t('send')}</button></div></form></section><section class="panel"><h2>${t('history')}</h2>${ds.length?`<div style="margin-top:18px">${ds.map(d=>`<div class="callout" style="margin:10px 0"><strong>${esc(d.subject)}</strong><div style="margin:9px 0">${status(d.status)}</div><p>${esc(d.detail)}</p>${d.resolution?`<p class="note positive">${esc(d.resolution)}</p>`:''}<small class="hint">${showDate(d.created_at)}</small></div>`).join('')}</div>`:empty(t('supportEmpty'),state.locale==='ru'?'Если возникла проблема, опишите её в форме.':'Describe any issue using the form.')}</section></div>`}
function team(){const orgs=state.me.organizations,org=orgs.find(x=>x.id===state.orgId),canInvite=org?.role==='owner';
 return `${pageTitle(t('teamTitle'),t('teamDesc'))}<div class="layout-two"><section class="panel"><h2>${t('memberships')}</h2><div style="margin-top:16px">${orgs.map(o=>`<div class="callout" style="margin-bottom:10px"><strong>${esc(o.name)}</strong><p>${esc(o.role)} · ${esc(o.plan||'free')}</p><button class="btn small ghost" data-action="switchorg" data-id="${o.id}">${t('open')}</button></div>`).join('')}</div><h2 style="margin-top:30px">${t('newOrg')}</h2><form class="form" id="orgForm" style="margin-top:14px"><div class="field"><label>${t('orgName')}</label><input class="input" name="name" minlength="2" maxlength="100" required></div><div><button class="btn ghost">${t('newOrg')}</button></div></form></section><section class="panel"><h2>${t('inviteTitle')}</h2><p class="note">${state.locale==='ru'?'Приглашение может создать только владелец. Передайте токен адресату вручную.':'Only the owner can invite. Share the invitation token directly with the recipient.'}</p>${canInvite?`<form class="form" id="inviteForm" style="margin-top:14px"><div class="field"><label>${t('inviteEmail')}</label><input type="email" name="email" class="input" required></div><div class="field"><label>${t('role')}</label><select name="role" class="select"><option value="editor">Editor</option><option value="viewer">Viewer</option></select></div><button class="btn primary">${t('invite')}</button></form>`:''}<div id="inviteResult"></div><h2 style="margin-top:35px">${t('acceptInvite')}</h2><form class="form" id="acceptInviteForm" style="margin-top:13px"><div class="field"><label>${t('inviteToken')}</label><input class="input" name="token" required></div><button class="btn ghost">${t('acceptInvite')}</button></form></section></div>`;}
function adminPage(){const a=state.cache.admin;if(!a)return empty('Loading','');const cases=a.cases||{};
 return `${pageTitle(t('adminTitle'),t('adminDesc'),`<button class="btn ghost" data-action="settle">${t('settle')}</button>`)}<div class="stats-grid">${[['Users',a.users],['Organizations',a.organizations],[t('fraud'),a.openFraud],[t('disputes'),a.openDisputes]].map(x=>`<div class="stat-card"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div></div>`).join('')}</div><div class="row-2"><div class="panel"><h2>${t('audit')}</h2><p class="note ${a.audit.ok?'positive':'warning'}">${a.audit.ok?t('valid'):t('failed')} · ${a.audit.checked} events</p></div><div class="panel"><h2>${t('ledger')}</h2><p class="note ${a.ledger.ok?'positive':'warning'}">${a.ledger.ok?t('valid'):t('failed')} · ${a.ledger.transactions} transactions</p></div></div><div class="layout-two" style="margin-top:19px"><section class="panel"><h2>${t('fraud')}</h2>${cases.fraud?.length?cases.fraud.map(f=>`<div class="callout" style="margin:13px 0"><strong>${esc(f.kind)}</strong><p>${esc(f.reason)}</p><div class="form-actions"><button class="btn small ghost" data-action="recheckfraud" data-buyer="${f.buyer_id}">${state.locale==='ru'?'Перепроверить':'Recheck'}</button><button class="btn small ghost" data-action="reviewfraud" data-id="${f.id}" data-status="cleared">${t('clear')}</button><button class="btn small danger" data-action="reviewfraud" data-id="${f.id}" data-status="confirmed">${t('confirm')}</button></div></div>`).join(''):empty(t('empty'),state.locale==='ru'?'Нет открытых сигналов':'No open signals')}</section><section class="panel"><h2>${t('disputes')}</h2>${cases.disputes?.length?cases.disputes.map(d=>`<div class="callout" style="margin:13px 0"><strong>${esc(d.subject)}</strong><p>${esc(d.detail)}</p><div class="form-actions"><button class="btn small ghost" data-action="reviewdispute" data-id="${d.id}" data-status="resolved">${t('resolve')}</button><button class="btn small danger" data-action="reviewdispute" data-id="${d.id}" data-status="rejected">${t('reject')}</button></div></div>`).join(''):empty(t('empty'),state.locale==='ru'?'Нет открытых претензий':'No open disputes')}</section></div><section class="panel" style="margin-top:19px"><h2>${t('payouts')}</h2><p class="note warning">${t('payoutWarn')}</p>${cases.payouts?.length?cases.payouts.map(p=>`<div class="callout" style="margin:12px 0"><strong>${fmt(p.amount_cents)}</strong><p>ID ${esc(p.id)} · ${esc(p.user_id.slice(0,8))}</p><div class="form-actions"><button class="btn small ghost" data-action="reviewpayout" data-id="${p.id}" data-status="approved">${t('approve')}</button><button class="btn small danger" data-action="reviewpayout" data-id="${p.id}" data-status="rejected">${t('reject')}</button></div></div>`).join(''):empty(t('empty'),'')}</section><section class="panel" style="margin-top:19px"><h2>${state.locale==='ru'?'Сверка платежей':'Payment reconciliation'}</h2><p class="note">${state.locale==='ru'?'Здесь сравнивается вручную загруженный отчёт с записями базы. Это не подтверждение от платёжной системы.':'Comparison of operator-supplied data with the ledger, not verified provider evidence.'}</p><form id="settlementForm" class="form" style="margin-top:16px"><div class="form-row"><div class="field"><label>Provider</label><input name="provider" class="input" value="SANDBOX_NO_REAL_MONEY" required></div><div class="field"><label>Report ID</label><input name="reportId" class="input" placeholder="batch-2026-001" required></div></div><div class="field"><label>Rows JSON (externalId, amountCents, refundedCents)</label><textarea name="rows" class="textarea" rows="4" required placeholder='[{"externalId":"pay-example","amountCents":129000,"refundedCents":0}]'></textarea></div><label class="note"><input type="checkbox" name="complete"> ${state.locale==='ru'?'Отчёт содержит все операции провайдера за всю историю':'Report includes all provider transactions in history'}</label><button class="btn primary" type="submit">${state.locale==='ru'?'Сверить':'Reconcile'}</button></form>${state.cache.settlementResult?`<p class="note">${esc(JSON.stringify(state.cache.settlementResult))}</p>`:''}<p class="note">${state.locale==='ru'?'Сохранено отчётов: ':'Saved reports: '}${(state.cache.settlementReports||[]).length}</p></section>`}

function projects(){const items=state.cache.projects||[],stats=state.cache.projectMetrics||{},q=(state.cache.quotes||[]).filter(x=>x.status==='accepted');
 const item=state.cache.selectedProject;
 return `${pageTitle(t('projects'),state.locale==='ru'?'Контроль реальной работы после принятия предложения.':'Track delivered work after a client accepts a proposal.',`<a class="btn ghost" href="/api/projects/export.csv?orgId=${encodeURIComponent(state.orgId)}">CSV</a>`)}
 <div class="stats-grid"><div class="stat-card"><div class="stat-label">${state.locale==='ru'?'Проекты':'Projects'}</div><div class="stat-value">${stats.projects||0}</div></div><div class="stat-card"><div class="stat-label">${state.locale==='ru'?'Приняты этапы':'Accepted milestones'}</div><div class="stat-value">${stats.accepted||0}/${stats.milestones||0}</div></div><div class="stat-card"><div class="stat-label">${state.locale==='ru'?'Завершённые проекты':'Completed'}</div><div class="stat-value">${stats.completed||0}</div></div><div class="stat-card"><div class="stat-label">${state.locale==='ru'?'Стоимость предложений, не выручка':'Quote value, not revenue'}</div><div class="stat-value">${fmt(stats.contractedValueCents||0)}</div></div></div>
 ${item?`<section class="panel" style="margin:22px 0"><div class="panel-head"><h2>${esc(item.title)}</h2><button class="btn small ghost" data-action="closeproject">×</button></div><p class="note">${esc(item.clientName)} · ${esc(item.status)} · ${esc(item.progress.accepted)} / ${esc(item.progress.total)} ${state.locale==='ru'?'принятых этапов':'accepted milestones'}</p><div class="proof-progress"><span style="width:${item.progress.percentage}%"></span></div><div class="form-actions" style="margin:18px 0"><button class="btn primary" data-action="shareproject" data-id="${item.id}">${state.locale==='ru'?'Ссылка заказчику':'Client portal link'}</button></div><div class="layout-two"><section><h3>${state.locale==='ru'?'Этапы работ':'Milestones'}</h3>${item.milestones.map(m=>`<div class="callout" style="margin:12px 0"><strong>${esc(m.title)}</strong><p>${esc(m.description||'')}</p><div class="tag-label">${esc(m.status)} · v${m.version}</div>${m.submittedSummary?`<p>${esc(m.submittedSummary)}</p>`:''}<div class="evidence-box"><div class="form-actions"><button class="btn small ghost" data-action="loadevidence" data-project-id="${item.id}" data-milestone-id="${m.id}">${state.locale==='ru'?'Вложения / обновить':'Attachments / refresh'}</button></div>${(state.cache.evidenceByStage?.[m.id]||[]).map(e=>`<p class="note">${esc(e.fileName)} · ${esc(e.status)} · ${Math.ceil(e.size/1024)} KiB ${!['submitted','accepted'].includes(m.status)&&e.status!=='revoked'?`<button class="btn small ghost" data-action="revokeevidence" data-project-id="${item.id}" data-milestone-id="${m.id}" data-id="${e.id}">${state.locale==='ru'?'Отозвать':'Revoke'}</button>`:''}</p>`).join('')}</div>${!['submitted','accepted'].includes(m.status)?`<form class="evidence-upload" data-project-id="${item.id}" data-milestone-id="${m.id}"><label>${state.locale==='ru'?'Доказательство (PDF/PNG/JPG/TXT, максимум 2 МиБ)':'Proof file (PDF/PNG/JPG/TXT, max 2 MiB)'}</label><input class="input" type="file" name="evidenceFile" accept=".pdf,.png,.jpg,.jpeg,.txt" required><button class="btn small ghost" type="submit">${state.locale==='ru'?'Зашифровать и загрузить':'Encrypt and upload'}</button><p class="note">${state.locale==='ru'?'Файл станет доступен клиенту только после независимой проверки':'Only independently scanned files can be shared'}</p></form>`:''}${!['submitted','accepted'].includes(m.status)?`<form data-project-id="${item.id}" data-milestone-id="${m.id}" class="delivery-submit"><label>${state.locale==='ru'?'Результат выполненной работы':'Delivery summary'}</label><textarea class="textarea" name="summary" minlength="10" maxlength="2000" required placeholder="${state.locale==='ru'?'Что выполнено и как проверить':'What has been delivered?'}"></textarea>${(state.cache.evidenceByStage?.[m.id]||[]).filter(e=>e.status==='cleared').map(e=>`<label class="note"><input type="checkbox" name="evidenceIds" value="${e.id}"> ${esc(e.fileName)}</label>`).join('')}<button class="btn small primary" type="submit">${state.locale==='ru'?'Отправить на согласование':'Submit for client review'}</button></form>`:''}</div>`).join('')||'<p class="note">No milestones</p>'}</section><section><h3>${state.locale==='ru'?'Добавить этап':'Add milestone'}</h3>${item.status==='active'?`<form id="milestoneForm" class="form"><div class="field"><label>${state.locale==='ru'?'Название':'Title'}</label><input class="input" name="title" required minlength="2" maxlength="140"></div><div class="field"><label>${state.locale==='ru'?'Описание':'Description'}</label><textarea class="textarea" name="description" maxlength="1500"></textarea></div><button class="btn primary" type="submit">${state.locale==='ru'?'Создать этап':'Create milestone'}</button></form>`:'<p>Project completed</p>'}</section></div></section>`:''}
 <section class="panel"><div class="panel-head"><h2>${state.locale==='ru'?'Заказы в работе':'Work in progress'}</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>${state.locale==='ru'?'Проект':'Project'}</th><th>${t('client')}</th><th>${t('status')}</th><th>${state.locale==='ru'?'Этапы':'Milestones'}</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.clientName)}</td><td>${status(x.status)}</td><td>${x.acceptedCount}/${x.milestoneCount}</td><td><button class="btn small ghost" data-action="openproject" data-id="${x.id}">${t('open')}</button></td></tr>`).join('')}</tbody></table></div>${items.length?'':empty(state.locale==='ru'?'Пока нет проектов':'No projects',state.locale==='ru'?'Клиент должен принять предложение по ссылке.':'A client must accept a proposal through a link.')}</section>
 ${q.length?`<section class="panel" style="margin-top:20px"><h2>${state.locale==='ru'?'Принятые предложения':'Accepted proposals'}</h2>${q.map(x=>`<div class="callout" style="margin-top:12px"><strong>${esc(x.title)}</strong> · ${esc(x.client_name||'—')} <button class="btn small ghost" data-action="launchproject" data-id="${x.id}">${state.locale==='ru'?'Начать проект':'Start project'}</button></div>`).join('')}</section>`:''}`;
}
function auth(){const register=state.authTab==='register';
 return `<div class="auth-page"><section class="auth-brand"><div class="brand"><div class="brand-logo">P</div><div><div class="brand-copy">OSMANX <span>PROOF</span></div><div class="brand-sub">WORK OPERATING SYSTEM</div></div></div><div><div class="overline">${t('productBadge')}</div><h1>${state.locale==='ru'?'Работа, которая <span>приносит результат.</span>':'Work that <span>gets done.</span>'}</h1><p>${t('authDesc')}</p></div><div class="note">OSMANX PROOF R2 · VALUE BEFORE REFERRALS</div></section><section class="auth-form-wrap"><div class="auth-card"><div class="overline">OSMANX PROOF / ACCOUNT</div><h2>${register?t('regTitle'):t('loginTitle')}</h2><p>${t('authDesc')}</p><div class="auth-tabs"><button class="${register?'active':''}" data-action="auth-register">${t('register')}</button><button class="${!register?'active':''}" data-action="auth-login">${t('login')}</button></div><form id="authForm" class="form" style="margin-top:25px">${register?`<div class="field"><label>${t('name')}</label><input class="input" name="name" autocomplete="name" minlength="2" maxlength="80" required></div>`:''}<div class="field"><label>${t('email')}</label><input class="input" name="email" type="email" autocomplete="email" required></div><div class="field"><label>${t('password')}</label><input class="input" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="10" maxlength="128" required></div>${register?`<div class="field"><label>${t('referralOptional')}</label><input class="input" name="referralCode" maxlength="80" value="${esc(new URLSearchParams(location.search).get('ref')||'')}"></div>`:''}<button type="submit" class="btn primary">${register?t('submitRegister'):t('submitLogin')} ${ic('arrow')}</button></form><p class="auth-footer">${t('authPrivacy')}</p><button class="text-button" data-action="locale">${state.locale==='ru'?'English':'Русский'}</button></div></section></div>`}
function render(){const root=el('root');root.innerHTML=!state.me?.authenticated?auth():shell(state.section==='overview'?overview():state.section==='quotes'?quotes():state.section==='projects'?projects():state.section==='billing'?billing():state.section==='referrals'?referrals():state.section==='support'?support():state.section==='team'?team():adminPage());if(el('quoteForm'))updateQuotePreview()}
async function navigate(section){if(section==='admin'&&!state.me.user.is_admin)return;state.section=section;state.editingQuote=null;await loadSection();render();window.scrollTo({top:0,behavior:'instant'});}
const decimalCents=s=>{const n=Number(s);if(!Number.isFinite(n)||n<0||Math.round(n*100)!==n*100&&Math.abs(n*100-Math.round(n*100))>1e-7)throw Error('Invalid currency value');return Math.round(n*100)};
function quoteInput(){const form=el('quoteForm');if(!form)throw Error('Missing quote form');const lines=[...form.querySelectorAll('[data-line]')].map(e=>({description:e.querySelector('[name=desc]').value.trim(),qty:Number(e.querySelector('[name=qty]').value),unitPriceCents:decimalCents(e.querySelector('[name=price]').value),unitCostCents:decimalCents(e.querySelector('[name=cost]').value)}));return {orgId:state.orgId,title:form.querySelector('[name=title]').value,clientName:form.querySelector('[name=clientName]').value,clientEmail:form.querySelector('[name=clientEmail]').value,items:lines,discountCents:decimalCents(form.querySelector('[name=discount]').value),taxBps:Math.round(Number(form.querySelector('[name=tax]').value)*100)}}
function updateQuotePreview(){try{const x=quoteInput(),subtotal=x.items.reduce((n,i)=>n+i.qty*i.unitPriceCents,0),cost=x.items.reduce((n,i)=>n+i.qty*i.unitCostCents,0),tax=Math.round((subtotal-x.discountCents)*x.taxBps/10000),due=subtotal-x.discountCents+tax;el('prevSubtotal').textContent=fmt(subtotal);el('prevTotal').textContent=fmt(due);el('prevMargin').textContent=(subtotal>x.discountCents?(((subtotal-x.discountCents-cost)/(subtotal-x.discountCents))*100).toFixed(1):'0')+'%'}catch{if(el('prevTotal'))el('prevTotal').textContent='—'}}
async function act(action,dataset){
 if(action==='locale'){state.locale=state.locale==='ru'?'en':'ru';if(state.me?.authenticated){await api('/me/locale',{method:'PATCH',body:{locale:state.locale}});state.me.user.locale=state.locale}render();return}
 if(action==='auth-register'||action==='auth-login'){state.authTab=action==='auth-register'?'register':'login';render();return}
 if(action==='logout'){await api('/auth/logout',{method:'POST',body:{}});state.me=null;state.cache={};state.orgId=null;render();return}
 if(action==='launchproject'){const x=await api('/projects',{method:'POST',body:{quoteId:dataset.id}});state.section='projects';await loadSection();state.cache.selectedProject=x.project;render();toast(t('saved'));return}
 if(action==='openproject'){state.cache.selectedProject=(await api(`/projects/${dataset.id}`)).project;render();return}
 if(action==='closeproject'){state.cache.selectedProject=null;render();return}
 if(action==='loadevidence'){
  const x=await api(`/projects/${dataset.projectId}/milestones/${dataset.milestoneId}/evidence`);
  (state.cache.evidenceByStage??={})[dataset.milestoneId]=x.evidence;render();return;
 }
 if(action==='revokeevidence'){
  if(!window.confirm(state.locale==='ru'?'Немедленно отозвать доступ к файлу?':'Revoke access to this file immediately?'))return;
  await api(`/projects/${dataset.projectId}/evidence/${dataset.id}`,{method:'POST',body:{reason:'Revoked by project owner after security review'}});
  const x=await api(`/projects/${dataset.projectId}/milestones/${dataset.milestoneId}/evidence`);
  (state.cache.evidenceByStage??={})[dataset.milestoneId]=x.evidence;render();toast(t('saved'));return;
 }
 if(action==='shareproject'){const x=await api(`/projects/${dataset.id}/share`,{method:'POST',body:{}});await copy(x.url);toast(t('linkReady')+': '+x.url);return}
 if(action==='newquote'){state.section='quotes';state.editingQuote={};await loadSection();render();return}
 if(action==='cancelquote'){state.editingQuote=null;render();return}
 if(action==='add-line'){el('quoteLines')?.insertAdjacentHTML('beforeend',lineEditor({},el('quoteLines').children.length));updateQuotePreview();return}
 if(action==='remove-line'){const lines=el('quoteLines');if(lines.children.length>1){document.activeElement.closest('[data-line]')?.remove();updateQuotePreview();}return}
 if(action==='viewquote'){const x=await api(`/quotes/${dataset.id}`);state.section='quotes';state.editingQuote=null;state.cache.selectedQuote=x.quote;await loadSection();render();el('root').querySelector('.page-title')?.insertAdjacentHTML('afterend',quoteDetail(x.quote));return}
 if(action==='closequote'){state.cache.selectedQuote=null;render();return}
 if(action==='editquote'){const q=state.cache.selectedQuote?.id===dataset.id?state.cache.selectedQuote:(await api(`/quotes/${dataset.id}`)).quote;state.editingQuote=q;render();return}
 if(action==='printquote'){window.open(`/api/quotes/${encodeURIComponent(dataset.id)}/print`,'_blank','noopener');return}
 if(action==='sharequote'){const x=await api(`/quotes/${dataset.id}/share`,{method:'POST',body:{}});await copy(x.url);toast(t('linkReady')+': '+x.url);return}
 if(action==='statusquote'){await api(`/quotes/${dataset.id}/status`,{method:'POST',body:{status:dataset.status}});state.cache.selectedQuote=null;await loadSection();render();toast(t('saved'));return}
 if(action==='subscription'){
  const actionName=dataset.change;const confirmText=actionName==='cancel'?(state.locale==='ru'?'Остановить новые счета? Уже оплаченный период не будет удалён.':'Stop future invoices? Paid access remains until expiry.'):(state.locale==='ru'?'Снова разрешить ручное создание счетов?':'Enable manual invoices again?');
  if(!window.confirm(confirmText))return;
  await api(`/subscriptions/${state.orgId}/${actionName}`,{method:'POST',body:{}});await loadSection();render();toast(t('saved'));return;
 }
 if(action==='invoice'){const x=await api('/invoices',{method:'POST',body:{orgId:state.orgId}});await loadSection();render();toast(t('invoice')+': '+x.invoice.id.slice(0,8));return}
 if(action==='sandboxpay'){const confirmed=window.confirm(state.locale==='ru'?'Это тестовая оплата: реальные деньги не списываются. Продолжить?':'This is a simulated payment. No money is charged. Continue?');if(!confirmed)return;await api('/sandbox/pay',{method:'POST',body:{orgId:state.orgId,invoiceId:dataset.id}});await loadMe();await loadSection();render();toast(t('simulation')+' · '+t('paid'));return}
 if(action==='copyref'){await copy(el('refLink').value);toast(t('linkReady'));return}
 if(action==='switchorg'){state.orgId=dataset.id;state.cache.selectedProject=null;state.cache.selectedQuote=null;await loadSection();render();return}
 if(action==='settle'){const x=await api('/admin/referrals/settle',{method:'POST',body:{}});await loadSection();render();toast('Settled: '+x.settled);return}
 if(action==='recheckfraud'){const x=await api(`/admin/referrals/${dataset.buyer}/recheck`,{method:'POST',body:{}});await loadSection();render();toast(`Risk signals: ${x.risk.signals.join(', ')||'none'}`);return}
 if(action==='reviewfraud'){await api(`/admin/fraud/${dataset.id}/review`,{method:'POST',body:{status:dataset.status}});await loadSection();render();return}
 if(action==='reviewdispute'){const resolution=window.prompt(state.locale==='ru'?'Напишите решение по обращению':'Enter dispute resolution');if(!resolution)return;await api(`/admin/disputes/${dataset.id}/review`,{method:'POST',body:{status:dataset.status,resolution}});await loadSection();render();return}
 if(action==='reviewpayout'){const confirmed=window.confirm(state.locale==='ru'?'Это только учётное одобрение. Реальная выплата НЕ будет отправлена.':'This is approval only. No money will be transferred.');if(!confirmed)return;await api(`/admin/payouts/${dataset.id}/review`,{method:'POST',body:{status:dataset.status}});await loadSection();render();return}
}
async function copy(value){try{await navigator.clipboard.writeText(value)}catch{const x=document.createElement('textarea');x.value=value;document.body.appendChild(x);x.select();document.execCommand('copy');x.remove()}}
document.addEventListener('click',async(event)=>{
 const button=event.target.closest('[data-action],[data-section]');if(!button||state.busy)return;
 event.preventDefault();state.busy=true;
 try{if(button.dataset.section)await navigate(button.dataset.section);else await act(button.dataset.action,button.dataset)}catch(e){toast(e.message,true)}finally{state.busy=false}
});
document.addEventListener('change',async(event)=>{
 if(event.target.id==='orgSelect'){state.orgId=event.target.value;state.cache.selectedProject=null;state.cache.selectedQuote=null;await loadSection();render()}
});
document.addEventListener('input',event=>{if(event.target.closest('#quoteForm'))updateQuotePreview()});
document.addEventListener('submit',async(event)=>{
 const form=event.target;if(!form?.id&&!form?.classList.contains('delivery-submit')&&!form?.classList.contains('evidence-upload'))return;event.preventDefault();if(state.busy)return;state.busy=true;
 const data=Object.fromEntries(new FormData(form));
 try{
  if(form.id==='authForm'){
   const x=await api(state.authTab==='register'?'/auth/register':'/auth/login',{method:'POST',body:data});
   await loadMe();state.section='overview';await loadSection();render();
  }else if(form.id==='quoteForm'){
   const b=quoteInput();if(state.editingQuote?.revision)b.expectedRevision=state.editingQuote.revision;const path=state.editingQuote?.id?`/quotes/${state.editingQuote.id}`:'/quotes',method=state.editingQuote?.id?'PATCH':'POST';await api(path,{method,body:b});state.editingQuote=null;await loadSection();render();toast(t('saved'));
  }else if(form.id==='milestoneForm'){
   const proj=state.cache.selectedProject;
   const x=await api(`/projects/${proj.id}/milestones`,{method:'POST',body:{title:data.title,description:data.description}});
   state.cache.selectedProject=x.project;await loadSection();render();toast(t('saved'));
  }else if(form.classList.contains('evidence-upload')){
   const file=form.querySelector('input[type="file"]')?.files?.[0];
   if(!file||file.size<1||file.size>2*1024*1024)throw Error('Максимум 2 МиБ / Maximum 2 MiB');
   const bytes=new Uint8Array(await file.arrayBuffer()),parts=[];
   for(let off=0;off<bytes.length;off+=8192)parts.push(String.fromCharCode(...bytes.subarray(off,off+8192)));
   const mime={'pdf':'application/pdf','png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','txt':'text/plain'}[file.name.split('.').pop().toLowerCase()];
   if(!mime)throw Error('PDF, PNG, JPEG or TXT only');
   await api(`/projects/${form.dataset.projectId}/milestones/${form.dataset.milestoneId}/evidence`,
    {method:'POST',body:{fileName:file.name,mime,contentBase64:btoa(parts.join(''))}});
   const x=await api(`/projects/${form.dataset.projectId}/milestones/${form.dataset.milestoneId}/evidence`);
   (state.cache.evidenceByStage??={})[form.dataset.milestoneId]=x.evidence;render();toast(state.locale==='ru'?'Файл зашифрован и находится в карантине до проверки':'Encrypted; awaiting independent scanner');
  }else if(form.classList.contains('delivery-submit')){
   const evidenceIds=[...form.querySelectorAll('input[name="evidenceIds"]:checked')].map(x=>x.value);
   const x=await api(`/projects/${form.dataset.projectId}/milestones/${form.dataset.milestoneId}/submit`,{method:'POST',body:{summary:data.summary,evidenceIds}});
   state.cache.selectedProject=x.project;await loadSection();render();toast(t('saved'));
  }else if(form.id==='disputeForm'){
   await api('/disputes',{method:'POST',body:{...data,orgId:state.orgId}});await loadSection();render();toast(t('saved'));
  }else if(form.id==='orgForm'){
   const x=await api('/orgs',{method:'POST',body:{name:data.name}});await loadMe();state.orgId=x.orgId;await loadSection();render();
  }else if(form.id==='inviteForm'){
   const x=await api(`/orgs/${state.orgId}/invite`,{method:'POST',body:data});el('inviteResult').innerHTML=`<div class="callout" style="margin-top:16px"><strong>Token</strong><p class="note">${esc(x.email)} · ${esc(x.role)}</p><div class="ref-code" style="font-size:11px;word-break:break-all">${esc(x.token)}</div><p class="note">${state.locale==='ru'?'Сохраните токен сейчас: повторно его нельзя получить.':'Copy this token now; it cannot be retrieved again.'}</p></div>`;
  }else if(form.id==='acceptInviteForm'){
   await api('/invitations/accept',{method:'POST',body:data});await loadMe();await loadSection();render();toast(t('saved'));
  }else if(form.id==='settlementForm'){
   let rows;try{rows=JSON.parse(data.rows)}catch{throw Error('Invalid settlement JSON')}
   const x=await api('/admin/settlements',{method:'POST',body:{provider:data.provider,reportId:data.reportId,rows,complete:data.complete==='on'}});
   state.cache.settlementResult={reportId:x.result.reportId,mismatches:x.result.mismatches,rows:x.result.rows};await loadSection();render();toast('Mismatches: '+x.result.mismatchCount);
  }else if(form.id==='payoutForm'){
   await api('/referrals/payouts',{method:'POST',body:{amountCents:decimalCents(data.amount)}});await loadSection();render();toast(state.locale==='ru'?'Заявка создана, деньги не перечислены':'Request created; no money transferred');
  }
 }catch(err){toast(err.message,true)}finally{state.busy=false}
});
(async()=>{try{await loadMe();if(state.me.authenticated)await loadSection();render()}catch(e){el('root').textContent='Startup error: '+e.message}})();
